@push('scripts')<script>document.addEventListener('input',event=>{if(!event.target.matches('[data-employee-performance-search]'))return;const query=event.target.value.trim().toLocaleLowerCase('vi');document.querySelectorAll('[data-employee-performance-list] tr[data-search]').forEach(row=>{row.hidden=query!==''&&!row.dataset.search.includes(query)})})</script>@endpush
